API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(RoutingDispatcher, "Routing & Dispatcher", "AWS API Gateway Routing", "Routes API requests to the appropriate backend microservices.")
    Component(AuthFilter, "Auth Filter", "AWS API Gateway Auth Filter", "Validates tokens and handles authentication for incoming requests.")
    Component(RateLimiter, "Rate Limiter", "AWS API Gateway Rate Limiter", "Limits request rates to ensure availability and prevent abuse.")
    Component(RequestTransformationCaching, "Request Transformation/Caching", "AWS API Gateway Transformation & Cache", "Transforms payloads and caches responses for low-latency page loads.")
}

Rel(AuthFilter, RoutingDispatcher, "Validates tokens and proxies payloads", "Internal Memory")

@enduml

Notification Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(notification_service, "Notification Service") {
    Component(Notification_Router_Component, "Notification Router Component", "Go", "Handles incoming gRPC requests and domain events.")
    Component(Template_Engine_Component, "Template Engine Component", "Go", "Compiles localized templates using Amazon DynamoDB.")
    Component(Dispatcher_Worker_Pool_Component, "Dispatcher Worker Pool Component", "Go", "Concurrent Go workers executing third-party API dispatches.")
    Component(Delivery_Status_Tracker_Component, "Delivery Status Tracker Component", "Go", "Records audit logs to Amazon Aurora PostgreSQL.")
    Component(Event_Consumer_Component, "Event Consumer Component", "Go", "Subscribes to the async event bus.")
}

Rel(Notification_Router_Component, Template_Engine_Component, "Invokes rendering", "in-memory function calls")
Rel(Template_Engine_Component, Dispatcher_Worker_Pool_Component, "Passes payloads", "Go channels")
@enduml

Amazon Aurora PostgreSQL & Amazon Dynamo.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_aurora_postgresql_amazon_dynamodb, "Amazon Aurora PostgreSQL & Amazon DynamoDB") {
    Component(Catalog_User_Relational_DB, "Catalog & User Relational DB", "Amazon Aurora PostgreSQL Multi-Region", "Stores structured book, review data, and provides ACID compliance for financial orders.")
    Component(Cart_Session_NoSQL_Store, "Cart & Session NoSQL Store", "Amazon DynamoDB Global Tables", "Delivers low-latency storage for shopping carts and sessions.")
}

Rel(Catalog_Search_Container, Catalog_User_Relational_DB, "Queries structured book/review data", "JDBC/SQL over TLS")
Rel(Order_Checkout_Container, Cart_Session_NoSQL_Store, "Reads/writes cart data", "AWS SDK / HTTPS")
@enduml
